import{S as d,o as c,c as s,a9 as r,B as a}from"./chunks/framework.IJ8axLs_.js";const n="/agentsrc/images/deepseek/06-selfmod-boundary.svg",i="/agentsrc/images/deepseek/06-hooks-bridge.svg",p="/agentsrc/images/deepseek/06-subagent-providers.svg",k=JSON.parse('{"title":"扩展的三个极致：自改、hooks 桥与跨产品委托","description":"","frontmatter":{"title":"扩展的三个极致：自改、hooks 桥与跨产品委托"},"headers":[],"relativePath":"deepseek/06-extensions.md","filePath":"deepseek/06-extensions.md","lastUpdated":1790217011000}'),l={name:"deepseek/06-extensions.md"},b=Object.assign(l,{setup(u){const e=[{question:"在当前的 `dsh` 里，模型对自己运行时的最大权力是？",options:["写并挂载临时插件","改写任一插件的配置行","只读地查看服务与注册树","卸载并重装任意 bundle"],correct:2,explanation:"tool-cordis 只给模型 cordis_inspect_list / cordis_inspect_query 两个只读工具；动态定义归程序与浏览器，持久安装归 Plugin Manager——no model tool creates dynamic definitions。A/D 是动态层的事，B 是 Plugin Manager 的事，都不归模型。"},{question:"一个 hook 以退出码 2 结束，意味着什么？",options:["阻断动作，stderr 作为理由","hook 崩溃，运行中断","请求确认后放行","结果被静默丢弃"],correct:0,explanation:"exit 2 是阻断信号：动作不发生，错误输出作为模型可见的理由。非 2 退出码才是非阻断失败（B 说反了），C 是 ask 语义，D 不存在。"},{question:"subagent 缝与 bash 缝的关键差异在于？",options:["subagent 不走 capability 缝","允许多 provider 按名共存","subagent 只支持进程内实现","bash 的 provider 也按名注册"],correct:1,explanation:"ctx.subagents 仿 LLM 适配器注册表：spawn/fork/acp/codex/claude-code/dsh-sdk 六个 provider 同时在场、按名选择；bash 是单一服务只挂一个执行器。A/C 与事实相反，D 张冠李戴。"},{question:"想要一套 hooks.json 覆盖不了的定制行为，`dsh` 的官方答案是？",options:["给桥提交扩展补丁","写原生 Cordis 插件","把逻辑拆成多个 hook 组合","用 MCP 服务器包装"],correct:1,explanation:"桥自我定位是 compatibility adapter, not a power tool：原生插件直接用全套 harness API，挂在同一批扩展点上，中间不再隔协议。A 违背定位，C/D 都绕不开协议的表达力上限。"},{question:'`fork-in-process` 起子代理时，"种子"是什么？',options:["父会话的全部原始事件","一份系统提示的快照","父日志已完成回合的前缀","父 agent 的工具注册表"],correct:2,explanation:"ContinuableCreateSpec 只携带区分新孩子与带种子孩子的东西：父日志的闭合前缀，与 04 篇会话 fork 同构。A 不要求闭合，C/D 不是 provider 侧的种子内容。"}];return(h,o)=>{const t=d("Quiz");return c(),s("div",null,[o[0]||(o[0]=r('<h1 id="扩展的三个极致-自改、hooks-桥与跨产品委托" tabindex="-1">扩展的三个极致：自改、hooks 桥与跨产品委托 <a class="header-anchor" href="#扩展的三个极致-自改、hooks-桥与跨产品委托" aria-label="Permalink to &quot;扩展的三个极致：自改、hooks 桥与跨产品委托&quot;">​</a></h1><p>前五篇把 <code>dsh</code> 的骨架拆完了：插件树怎么装配（01）、靠什么原语共存（02）、默认驱动怎么跑回合（03）、会话日志怎么当唯一事实源（04）、能力怎么做成可换的缝（05）。终章看三件把&quot;可扩展&quot;推到头的事：agent 碰自己的运行时、翻译别家的 hook 协议、把活儿委托给另一个产品里的 agent。</p><p>这三件事放在一起，是因为它们共用同一个底层判断：<strong>扩展永远落在插件树的扩展点上，引擎本身不为任何一家需求改形状。</strong> 读完这一篇，你会带着三个问题的答案离开：</p><ul><li>agent 对自己运行时的权力边界画在哪里，为什么模型侧只剩&quot;看&quot;？</li><li>已经在 Claude Code 里养好的 hooks，凭什么原样搬进 <code>dsh</code> 就能跑？</li><li>委托给 Codex 或 Claude Code 的子任务，凭什么和本地孩子共用一个接口？</li></ul><p>MCP 与 ACP 的接入最后带一段。这是全系列的收尾。</p><h2 id="一、自改的边界-看、临时挂、持久装" tabindex="-1">一、自改的边界：看、临时挂、持久装 <a class="header-anchor" href="#一、自改的边界-看、临时挂、持久装" aria-label="Permalink to &quot;一、自改的边界：看、临时挂、持久装&quot;">​</a></h2><p>&quot;agent 改自己&quot;是 <code>dsh</code> 最容易被浪漫化的部分，先把边界画准。它实际是一个三层结构，每层给不同的操作者：</p><p><strong>第一层，模型只拿只读。</strong> <code>tool-cordis</code> 提供给模型两个工具：<code>cordis_inspect_list</code> 发现运行时可查的 provider，<code>cordis_inspect_query</code> 查某个 provider 的精确方法与类型。Host 侧的 Config provider 还能列出 Loader 树里活着的每个 entry：它的 id、patch 寻址用的树内 id、Config 状态（schema 校验通过 / 缺席 / 不支持 / 组与 include 承载行的 tree / 未激活），以及把某个 entry 的 Config 投影成一份自包含的 JSON Schema 文档。模型的全部权力是&quot;看清自己在什么里面跑&quot;。</p><p><strong>第二层，动态定义归程序与浏览器。</strong> <code>cordis-host-runner</code> 维护一套进程内的动态包注册表，<code>define</code> / <code>run</code> / <code>stop</code> / <code>undefine</code> 四个动词归<strong>程序化调用方</strong>，浏览器面板只操作已存在的定义——README 的措辞很明确：no model tool creates dynamic definitions。</p><p>定义分两半：Host 半跑在 <code>node:vm</code> 隔离域里，同步段的执行时间受 <code>vmTimeoutMs</code> 约束；带浏览器半的包要先经过批准往返——服务发出 <code>cordis/request-run</code>，挂起的请求由应答页面走完 <code>runHostHalf</code> / <code>getClientCode</code> / <code>resolveRequestRun</code> 才提交激活。<code>stop</code> 收回活的效果但保留定义、可再 <code>run</code>；<code>undefine</code> 连定义一起忘掉。定义是<strong>会话作用域、进程本地</strong>的：别的会话看不见，重启即清空。</p><p><strong>第三层，持久变更归 Plugin Manager。</strong> 要装一个真插件，走 <code>dsh plugin</code>——安装含插件代码或 MCP 配置的 bundle、启用、禁用，全部落进 profile。<code>dsh-base</code> 的装配链（01 篇）就是它的操作对象。</p><p><img src="'+n+'" alt="自改的三层边界：只读 inspect、动态定义、持久安装"></p><p>三层的信任姿态一以贯之。vm 隔离的全局污染，但 README 写得直白：<strong>The sandbox isolates globals but is not a security boundary</strong>——动态包声明的服务能触达活运行时，&quot;Treat a dynamic package like bash access&quot;。</p><p>设计上还有两处值得记：注册表与沙箱是同一个服务（<code>DynamicCordisRunnerService</code> 独占定义注册、vm 沙箱、fiber 生命周期、invoke handler 表，一个定义的一生只有一个 owner）；版本是不可变的包（<code>define</code> 之后内容永不改，<code>run</code> 与 <code>update</code> 靠 <code>currentPackageId</code> / <code>nextPackageId</code> 指向运行版与目标版来区分）。</p><p>把三层合起来看，<code>dsh</code> 对&quot;自改&quot;的态度清楚了：<strong>看见，随时可以；临时挂载，程序可以、模型不行；持久安装，走正规装配。</strong> 模型被当作运行时里最需要防的参与者——这与工具裁决链（05 篇）把参数进闸焊死是同一种哲学。</p><h2 id="二、hooks-桥-翻译协议-不动引擎" tabindex="-1">二、hooks 桥：翻译协议，不动引擎 <a class="header-anchor" href="#二、hooks-桥-翻译协议-不动引擎" aria-label="Permalink to &quot;二、hooks 桥：翻译协议，不动引擎&quot;">​</a></h2><p>已经住在 Claude Code 生态里的人，手里的 <code>hooks.json</code> 是现成资产。<code>dsh</code> 接它的方式不是实现一套 CC 的 hook 机制，而是做<strong>翻译</strong>：<code>dsh-hooks-claude-code</code> 读你的配置文件，把每个 hook 事件映射到 <code>dsh</code> 自己的拦截点上。</p><p>共享核心抽成了 <code>dsh-hook-protocol</code> 库——它不是插件、不注入任何东西，只定义&quot;一个 hook 能做什么、跑了会发生什么&quot;。处理管线是一条单职责函数链：校验 matcher 模式 → 经 <code>dsh-shell</code> 执行器跑命令 → 解码退出码与 stdout → 按 most-restrictive 合并（<code>deny &gt; ask &gt; allow</code>，<code>continue: false</code> 的停机请求有粘性，上下文按序累加）→ 落一对 <code>hook/invoked</code> / <code>hook/result</code> 日志事件。</p><p>两个方言唯一的分歧轴是 matcher 的解释方式：CC 把模式当字面量备选或正则，Codex 恒当非锚定正则——一个 <code>mode</code> 参数收掉了全部方言差异。</p><p>hook 的能力词汇就五种：exit 2 阻断（stderr 作为模型可见的理由）、请求确认（仅 CC 方言）、附加上下文（模型下次请求可见）、请求停机（记录但无运行级效果，拦截点还没有硬停原语）、以及非 2 退出码的非阻断失败。设计纪律只有一条，处处体现：<strong>绝不让 hook 砸掉调用它的 turn</strong>——非法正则算不匹配、执行器拒绝变成无退出码的输出、任何解析失败都降级为受控结果。</p><p>CC 桥支持七个事件，映射关系是这一篇的骨架：</p><table tabindex="0"><thead><tr><th>你的 hook</th><th>落点</th><th>能做什么</th></tr></thead><tbody><tr><td><code>SessionStart</code></td><td><code>agent/created</code> 初始化</td><td>附加上下文，赶在第一个 turn 前</td></tr><tr><td><code>UserPromptSubmit</code></td><td><code>agent/pre-step</code> 瀑布</td><td>阻断提示，或附加上下文</td></tr><tr><td><code>PreToolUse</code></td><td><code>tools/pre-execute</code> 瀑布</td><td>阻断工具，或请求审批</td></tr><tr><td><code>PostToolUse</code></td><td><code>tools/post-execute</code> 瀑布</td><td>带反馈阻断结果，或附加上下文</td></tr><tr><td><code>Stop</code></td><td><code>agent/turn-stopping</code> serial</td><td>阻断收尾、经 <code>steer()</code> 强制再走一步</td></tr><tr><td><code>SubagentStart</code></td><td><code>subagent/start</code></td><td>给活着的进程内子代理注入上下文</td></tr><tr><td><code>SubagentStop</code></td><td><code>subagent/end</code></td><td>只观察</td></tr></tbody></table><p><img src="'+i+'" alt="hooks 的翻译路径：外部协议到 typed 拦截点"></p><p>两个细节体现翻译的诚实。其一，只附加上下文的 hook 必须先 <code>next()</code> 委托再把自己的消息折进下游决策——后面别的监听者仍然可以拒绝或改写，&quot;加料&quot;没有否决权。</p><p>其二，桥的 README 把不支持的部分列成了清单：CC 当前的 30 个 hook 事件里支持 7 个，<code>transcript_path</code> 恒为空串（持久化缝不暴露产物路径，zstd 压缩的会话日志 hook 脚本也读不了），<code>updatedInput</code> 解析但不生效。定位一句话说尽：<strong>A compatibility adapter, not a power tool</strong>——要定制行为，写原生 Cordis 插件，直接用全套 harness API，中间不再隔一层协议。</p><h2 id="三、subagent-缝-一张按名共存的注册表" tabindex="-1">三、subagent 缝：一张按名共存的注册表 <a class="header-anchor" href="#三、subagent-缝-一张按名共存的注册表" aria-label="Permalink to &quot;三、subagent 缝：一张按名共存的注册表&quot;">​</a></h2><p>第五篇讲过 bash 缝的&quot;同层互斥&quot;：一个组合只能挂一个执行器。subagent 缝是反例，也是它最有信息量的地方——<code>ctx.subagents</code> 是一张<strong>按名注册、多 provider 共存</strong>的注册表，结构仿的是 LLM 适配器注册表。文档原话：subagent 与 bash 一样是 optional capability、不在 agent loop 里，但它因为<strong>多个实现同时在场</strong>而不同。</p><p>在场的是六个 provider：<code>spawn-in-process</code>（进程内新孩子）、<code>fork-in-process</code>（用父会话已完成的历史做种子的进程内孩子）、<code>acp</code>（走 Agent Client Protocol 的进程外孩子）、<code>codex</code>（官方 app-server 协议驱动的真 Codex）、<code>claude-code</code>（官方 Agent SDK 驱动的真 Claude Code）、<code>dsh-sdk</code>（进程外 Harness 孩子经 TypeScript SDK）。模型面的 Consumer 是 <code>tool-subagent</code>（按 provider 委托）加 <code>tool-subagent-control</code>（<code>send_message</code>、<code>interrupt_agent</code>、<code>list_agents</code>）。</p><p><img src="'+p+'" alt="ctx.subagents 上按名共存的六个 provider"></p><p>能力的声明分两条路，这个区分很讲究。<strong>一次性 start 的能力</strong>标在 provider 的静态描述符上，服务在 start 之前检查：请求里用到一个 provider 缺的能力，直接以 <code>SubagentError(&#39;UNSUPPORTED_CAPABILITY&#39;)</code> 拒绝——fail loud，绝不先接受再忽略。<strong>可续跑（continuable）孩子的能力</strong>则用类型系统表达：provider 实现了可选方法 <code>prepareContinuable</code>，这个方法的存在本身就是能力，TS 的类型窄化就是发现机制。</p><p>continuable 是这套设计里最完整的一条线：<code>startContinuable</code> 预留稳定的子 id、快照版本化的 <code>subagent/descriptor</code>、向 provider 要一份<strong>纯数据</strong>的创建规格（只携带区分&quot;新孩子&quot;与&quot;带种子孩子&quot;的东西——比如父日志已完成回合的前缀），再经私有 activation-owner scope 创建子 Agent、投递首条 prompt。</p><p>冷恢复根本不经过 provider：续跑管理器折叠描述符、直接调 <code>ctx.agents.resume()</code>。fork 的种子语义与 04 篇的会话 fork 同构——子会话从父日志的一段闭合前缀起步，provider 只负责&quot;怎么读父历史&quot;这一小段。</p><p>跨产品的意义在这里收口：委托给 Codex 或 Claude Code 的一次任务，与本地 spawn 的孩子，对模型来说是同一个 <code>tool-subagent</code> 接口下的不同 provider 名。第五篇的&quot;换 provider 不动 Consumer&quot;，在这里直接跨出了 <code>dsh</code> 自家的进程边界。</p><h2 id="四、mcp-与-acp-接入生态也是插件" tabindex="-1">四、MCP 与 ACP：接入生态也是插件 <a class="header-anchor" href="#四、mcp-与-acp-接入生态也是插件" aria-label="Permalink to &quot;四、MCP 与 ACP：接入生态也是插件&quot;">​</a></h2><p>顺着&quot;接别人的协议&quot;再补两块拼图。<code>mcp-client</code> 连接一个 MCP 服务器，把它的工具与指令暴露进 <code>ctx.tools</code>、资源操作经 <code>mcp-resources</code> 以显式选服务器的共享工具提供；<code>acp</code> 组让外部程序经 ACP 管理持久 agent、挂 MCP 服务器、选模型、下发与取消任务。两件事都没有专门的一章，因为机制上前文全部覆盖：MCP 服务器就是一组注册进来的工具，ACP 是一个进程外的驱动方——它们出现在 <code>dsh</code> 里是插件，离开时 <code>dsh</code> 不记得它们来过。</p><h2 id="五、终局-两根柱子" tabindex="-1">五、终局：两根柱子 <a class="header-anchor" href="#五、终局-两根柱子" aria-label="Permalink to &quot;五、终局：两根柱子&quot;">​</a></h2><p>六篇走完，<code>dsh</code> 的骨架可以收进两根柱子。<strong>一根是 Cordis 插件树</strong>：一切皆插件、注册即副作用、无特权核心——从循环本身到沙箱后端到 hooks 桥，全部是树上的挂件。<strong>一根是会话日志</strong>：追加式事件流是唯一事实源，模型上下文、回放、持久化、fork、压缩的表面替换，全是它的投影，invariant 逐请求断言&quot;模型可见即已落日志&quot;。</p><p>三件极致的事放回这个坐标系：自改是插件树对&quot;自己&quot;的最后一次自我应用——连&quot;看和改自己&quot;都拆成了三层插件；hooks 桥是外部生态到扩展点的翻译器——引擎保持中立，方言差异被压进一个 <code>mode</code> 参数；跨产品委托是缝机制的越境——provider 注册表跨出了自家进程。它们没有一件需要引擎开口子，这就是全系列反复验证的那个判断的最终形态。</p><p>与三个终端 Agent 的最后一照：</p><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode / Codex / Claude Code</th><th>DeepSeek Harness</th></tr></thead><tbody><tr><td>定位</td><td>产品</td><td>被装配的引擎</td></tr><tr><td>扩展</td><td>产品内的钩子与模块</td><td>一切皆插件，含循环与日志的消费者</td></tr><tr><td>兼容生态</td><td>各自的原生协议</td><td>桥翻译 CC/Codex hooks、MCP、ACP</td></tr><tr><td>委托</td><td>各自的子 agent</td><td>同一注册表下本地与跨产品共存</td></tr></tbody></table><p>三个终端 Agent 选择了把一件事做到开箱即用；<code>dsh</code> 选择了把&quot;被任意产品装配&quot;贯彻到底，代价是每个使用者都要先理解一棵树的语法。哪种都对——前者服务今天的产品，后者赌的是明天会有很多个产品。</p><p>至此，DeepSeek Harness 源码精读六篇完结，感谢读完。</p><h2 id="源码索引" tabindex="-1">源码索引 <a class="header-anchor" href="#源码索引" aria-label="Permalink to &quot;源码索引&quot;">​</a></h2><ul><li><code>packages/extensions/tool-cordis/README.md</code> — 只读 inspect 工具</li><li><code>packages/extensions/cordis-host-runner/README.md</code> — 动态定义注册表、vm 沙箱、信任姿态</li><li><code>packages/boot/plugin-manager/</code> — 持久 bundle 安装</li><li><code>packages/hooks/hook-protocol/README.md</code> — 共享 hook 规则、合并语义、<code>hook/*</code> 事件</li><li><code>packages/hooks/hooks-claude-code/README.md</code> — 七事件映射表与支持边界</li><li><code>packages/subagent/README.md</code> — 委托缝包族</li><li><code>docs/subsystems/subagent.md</code> — provider 契约、能力发现、continuable</li><li><code>packages/mcp/README.md</code>、<code>packages/acp/README.md</code> — 生态接入</li><li><code>docs/subsystems/extensions.md</code> — 生成的 <code>ctx.cordisInspect</code> / <code>ctx.dynamicCordisRunner</code> API</li></ul><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>',45)),a(t,{questions:e})])}}});export{k as __pageData,b as default};
